import React from 'react';
import { Link } from 'react-router-dom';
import { useGetFormsQuery } from '../generated/graphql';

const HomePage: React.FC = () => {
  const { data, isLoading, error } = useGetFormsQuery();

  if (isLoading) return <div className="p-8">Loading forms...</div>;
  if (error) return <div className="p-8 text-red-500">Error loading forms.</div>;

  return (
    <div className="max-w-4xl mx-auto p-8">
      <div className="flex justify-between items-center mb-8">
        <h1 className="text-3xl font-bold">Google Forms Lite</h1>
        <Link
          to="/forms/new"
          className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"
        >
          Create New Form
        </Link>
      </div>

      <div className="grid gap-4">
        {data?.forms.map((form) => (
          <div key={form.id} className="border p-4 rounded shadow-sm flex justify-between items-start">
            <div>
              <h2 className="text-xl font-semibold">{form.title}</h2>
              <p className="text-gray-600">{form.description}</p>
            </div>
            <div className="flex gap-2">
              <Link
                to={`/forms/${form.id}/fill`}
                className="text-blue-600 hover:underline"
              >
                View Form
              </Link>
              <span className="text-gray-300">|</span>
              <Link
                to={`/forms/${form.id}/responses`}
                className="text-blue-600 hover:underline"
              >
                View Responses
              </Link>
            </div>
          </div>
        ))}
        {data?.forms.length === 0 && (
          <p className="text-center text-gray-500 py-8 border-2 border-dashed rounded">
            No forms created yet.
          </p>
        )}
      </div>
    </div>
  );
};

export default HomePage;
